# To optimize, we only need to consider the maximum possible values for q_i.
# Since we want to maximize the score, and the score is a sum of q_i with positive coefficients,
# we should try the largest possible values for each q_i.

def solve_fast_v2():
    min_S = float('inf')
    for q0 in range(203):
        for q1 in range((q0 // 9) + 1):
            for q2 in range(((q0 + q1) // 9) + 1):
                for q3 in range(((q0 + q1 + q2) // 10) + 1):
                    for q4 in range(((q1 + q2 + q3) // 10) + 1):
                        for q5 in range(((q2 + q3 + q4) // 10) + 1):
                            for q6 in range(((q3 + q4 + q5) // 10) + 1):
                                max_q7 = min(9 - q5 - q6, (q4 + q5 + q6) // 10)
                                if max_q7 < 0: continue
                                # To minimize S, we want the largest possible q_i.
                                # Let's try the largest q7 and a few smaller ones.
                                for q7 in range(max_q7, max(-1, max_q7-2), -1):
                                    q8 = (q5 + q6 + q7) // 10
                                    if q8 == 0:
                                        qs = [0]*101
                                        qs[0], qs[1], qs[2], qs[3], qs[4], qs[5], qs[6], qs[7], qs[8] = q0, q1, q2, q3, q4, q5, q6, q7, q8
                                        ks = [0]*101
                                        ks[0] = 2025 - 10*qs[0]
                                        ks[1] = qs[0] - 9*qs[1]
                                        ks[2] = qs[0] + qs[1] - 9*qs[2]
                                        for i in range(3, 101):
                                            q_prev1 = qs[i-1] if i-1 >= 0 else 0
                                            q_prev2 = qs[i-2] if i-2 >= 0 else 0
                                            q_prev3 = qs[i-3] if i-3 >= 0 else 0
                                            q_curr = qs[i] if i <= 97 else 0
                                            ks[i] = q_prev3 + q_prev2 + q_prev1 - 10*q_curr
                                        if all(k >= 0 for k in ks):
                                            min_S = min(min_S, sum(ks))
                                            # Since we're iterating q7 downwards, 
                                            # the first one that satisfies k_i >= 0 will likely give the smallest S.
                                            # But let's check a few.
                                            break
    return min_S

