def check(ks):
    a_coeffs = []
    def get_coeffs(n):
        if n == 0: return (1, 0, 0)
        if n == 1: return (0, 1, 0)
        if n == 2: return (0, 0, 1)
        a0, a1, a2 = get_coeffs(n-1)
        return (10 * a2, a0 - a2, a1 - a2)

    for i in range(101):
        a_coeffs.append(get_coeffs(i))

    sum_a0 = sum(ks[i] * a_coeffs[i][0] for i in range(101))
    sum_a1 = sum(ks[i] * a_coeffs[i][1] for i in range(101))
    sum_a2 = sum(ks[i] * a_coeffs[i][2] for i in range(101))

    return sum_a0 == 2025, sum_a1 == 0, sum_a2 == 0

